INSERT INTO "listings" ("listing_id","category","title","city","district","community","price_minor","area_sqm","rooms","metro","attrs_json","description","photos_json","agent_id","owner_user_id","status","listed_at") VALUES ('apt_maple_lane_2b_0603','rent','Maple Lane 76 sqm two-bedroom renovated in 2023','Hangzhou','Binjiang','Maple Lane',1060000,76.0,2,'Metro Line 6 Xinghe Station 780m','{"available_from": "2026-08-10", "property_fee_minor": 32000, "renovated_at": "2023-04", "ventilation_days_possible": 15, "elevator": true, "floor": 6, "balcony_guardrail_cm": 118, "window_locks": "installed", "written_terms": "draft_available", "air_report": "not_recent", "mold_risk": "low"}','Renovated in April 2023; the sixth floor has an elevator, and the balcony railing is listed as 118 centimeters. The landlord said the contract appendix can specify window locks, maintenance response, contamination remediation, and deposit refund terms. Property fees are 320 yuan per month.','["Child''s room","Hallway","Window lock"]','agt_wang',NULL,'active','2026-07-11T09:00:00+08:00');
